import ezdxf, os, sys
d = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\20-11-2026\521120-07\Sua_loi'
for c in ['26-070496', '26-070497', '26-070498', '26-070499']:
    for s in 'TF':
        doc = ezdxf.readfile(os.path.join(d, c + s + '.dxf'))
        print('=====', c, s)
        rows = []
        for e in doc.modelspace():
            t = e.dxftype()
            if t == 'LINE':
                g = '(%.2f,%.2f)-(%.2f,%.2f)' % (e.dxf.start.x, e.dxf.start.y, e.dxf.end.x, e.dxf.end.y)
            elif t == 'CIRCLE':
                g = 'C(%.2f,%.2f) r%.2f' % (e.dxf.center.x, e.dxf.center.y, e.dxf.radius)
            elif t == 'ARC':
                g = 'ARC(%.2f,%.2f) r%.2f %.0f-%.0f' % (e.dxf.center.x, e.dxf.center.y, e.dxf.radius, e.dxf.start_angle, e.dxf.end_angle)
            else:
                g = t
            rows.append((e.dxf.layer, t, g, e.dxf.get('color', '')))
        rows.sort()
        for r in rows:
            print(*r)

